import{_ as t,o,c as a,ae as s}from"./chunks/framework.Dn6zxbF8.js";const g=JSON.parse('{"title":"Project namespaces","description":"","frontmatter":{"id":"0752163629","title":"Project namespaces","state":"Draft","created":"2026-11-02T00:00:00.000Z","tags":["directory","monorepo","ownership"],"category":"Platform"},"headers":[],"relativePath":"adrs/0752163629/README.md","filePath":"adrs/0752163629/README.md"}'),r={name:"adrs/0752163629/README.md"};function n(i,e,c,d,p,h){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="project-namespaces" tabindex="-1">Project namespaces <a class="header-anchor" href="#project-namespaces" aria-label="Permalink to &quot;Project namespaces&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><a href="./../9316364013/README.html">ADR#9316364013</a> fixes the directories at the repository root, and <a href="./../5842232571/README.html">ADR#5842232571</a> splits source by language toolchain. Both read as if the repository holds one thing. A repository that hosts several, such as products, platform systems and experiments, spreads each of them across every root directory, with no single place that holds all of one thing.</p><p>Most of the time that is fine: each thing shows up as a namespace segment the tools already provide, such as a crate prefix, a protobuf package path or a chart name. It stops being fine when one thing has its own owner and release cadence, or is an experiment that has to be deleted without touching anything else. A survey of our repositories found those cases solved ad hoc, with <code>experiments/</code> at the root and product names as root directories next to the language workspaces.</p><p>Putting maturity in the path, as <code>experiments/</code> does, makes graduation a move. A move breaks import paths, CI filters, ownership rules and links, so an experiment that succeeds changes its address exactly when people start depending on it.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><h3 id="the-root-project" tabindex="-1">The root project <a class="header-anchor" href="#the-root-project" aria-label="Permalink to &quot;The root project&quot;">​</a></h3><ul><li>You <strong>MUST</strong> treat the repository root as a project with no name. Everything not moved into <code>projects/</code> lives in the root directories, and is not limited to code that named projects share.</li><li>You <strong>SHOULD</strong> tell apart the things the root holds by a namespace segment inside the root directories: a crate or package name prefix, a protobuf package path, an image or chart name, an OpenTelemetry registry domain.</li></ul><h3 id="named-projects" tabindex="-1">Named projects <a class="header-anchor" href="#named-projects" aria-label="Permalink to &quot;Named projects&quot;">​</a></h3><ul><li>You <strong>SHOULD NOT</strong> create <code>projects/</code> until a thing needs isolation that a namespace segment cannot give it: its own owner, its own release cadence, or deletion as a unit. You <strong>MUST NOT</strong> create it in anticipation of a second thing, and a repository that holds one thing never has it.</li><li>You <strong>MAY</strong> then move that thing into <code>projects/&lt;project&gt;/</code>, named in kebab-case. You <strong>MUST</strong> use the same name as the prefix of the crates, packages, images and charts it produces.</li><li>You <strong>MUST</strong> place what a project owns inside <code>projects/&lt;project&gt;/</code>: its language workspaces per <a href="./../5842232571/README.html">ADR#5842232571</a>, its <code>docs/</code> and its <code>README.md</code>. A project that runs its own mise tasks <strong>MUST</strong> be a nested mise configuration root per <a href="./../6647967335/README.html">ADR#6647967335</a>.</li><li>You <strong>MUST NOT</strong> nest <code>projects/</code> inside a project.</li><li>You <strong>MUST NOT</strong> encode maturity or kind in the path. <code>experiments/</code>, <code>labs/</code>, <code>sandbox/</code>, <code>products/</code> and <code>apps/</code> are not containers for projects. You <strong>MUST</strong> state the lifecycle in a line directly under the title of the project&#39;s <code>README.md</code>, as <code>Status: experimental</code>, <code>Status: active</code> or <code>Status: deprecated</code>, and change that line instead of moving the directory.</li><li>You <strong>SHOULD</strong> move a project to its own repository when nothing requires it to share this one. Extraction takes <code>projects/&lt;project&gt;/</code> as the new root, plus every path under its namespace segment in the shared root directories. Every root path the dependency graph lists for the project <strong>MUST</strong> first be published as a versioned package the project consumes, or be copied into it, so the extracted repository builds on its own.</li></ul><h3 id="shared-root-directories" tabindex="-1">Shared root directories <a class="header-anchor" href="#shared-root-directories" aria-label="Permalink to &quot;Shared root directories&quot;">​</a></h3><ul><li><p>You <strong>MUST</strong> keep <code>.github/</code> at the repository root, because GitHub reads it nowhere else.</p></li><li><p>You <strong>SHOULD</strong> keep <code>.config/</code>, <code>devops/</code>, <code>otel/</code> and the schema source directories <code>proto/</code>, <code>wit/</code>, <code>openapi/</code> and <code>asyncapi/</code> at the repository root, shared by the root project and every named project. One buf module, one semantic convention registry and one operational estate that see every project at once catch conflicts that separate copies hide.</p></li><li><p>You <strong>MUST</strong> lay out those root directories to hold several projects side by side, each under its namespace segment: <code>proto/&lt;org&gt;/&lt;project&gt;/</code>, <code>wit/&lt;project&gt;/</code>, <code>openapi/&lt;project&gt;/</code>, <code>asyncapi/&lt;project&gt;/</code>, <code>otel/registry/&lt;vendor&gt;/&lt;project&gt;/</code>, <code>devops/docker/images/&lt;project&gt;-*/</code>, <code>devops/helm/charts/&lt;project&gt;-*/</code>.</p></li><li><p>You <strong>MAY</strong> nest any of those directories inside <code>projects/&lt;project&gt;/</code> when the project cannot share the root copy, such as a separate buf module or an operational estate no other project touches. The nested copy follows the same ADR as the root one, and the project&#39;s share <strong>MUST NOT</strong> then also live in the root copy.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.</span></span>
<span class="line"><span>├── .github/  .config/  devops/  otel/  proto/   # shared, one segment each</span></span>
<span class="line"><span>├── rsworkspace/  docs/                           # the root project</span></span>
<span class="line"><span>└── projects</span></span>
<span class="line"><span>    └── &lt;project&gt;</span></span>
<span class="line"><span>        ├── README.md                             # Status: experimental</span></span>
<span class="line"><span>        ├── .config/mise/tasks/                   # its own tasks only</span></span>
<span class="line"><span>        ├── .config/mise/lib/</span></span>
<span class="line"><span>        ├── rsworkspace/</span></span>
<span class="line"><span>        ├── goworkspace/</span></span>
<span class="line"><span>        └── docs/</span></span></code></pre></div></li></ul><h3 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h3><ul><li>You <strong>MUST</strong> keep dependencies pointing inward from the root. A project <strong>MAY</strong> depend on the root workspaces and the shared root directories. The root <strong>MUST NOT</strong> depend on a project, and a project <strong>MUST NOT</strong> depend on another project. Code two projects need lives in the root.</li><li>You <strong>MUST</strong> derive the dependency graph from the toolchain manifests, such as <code>cargo metadata</code>, <code>go list -deps</code> and the pnpm workspace, plus the namespace segments in the shared root directories. You <strong>MUST NOT</strong> maintain a list of dependencies by hand.</li><li>You <strong>MUST</strong> expose the graph as a mise task that prints, as JSON, every project with the paths it owns and the root paths it depends on. The root project owns every path outside <code>projects/</code>.</li><li>You <strong>MUST</strong> compute CI path filters, sparse checkouts and affected-project selection from that output, and <strong>MUST NOT</strong> write the paths into a workflow by hand. A change under <code>.config/</code> affects every project.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Each project carries its own lockfile per language, so its dependency versions drift from the root and from other projects. That is the price of isolation, and the reason the namespace segment stays the default.</li><li>A project that depends on code in the root takes it as a path dependency across workspaces instead of as a workspace member, and the graph picks the edge up from the manifest.</li><li>A project&#39;s sparse checkout is its directory, the shared root directories and the root paths the graph lists. The shared directories are taken whole, which keeps git in cone mode.</li><li>Graduating an experiment is a one-line change to its <code>README.md</code>, and deleting one is deleting its directory and its namespace paths.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./../9316364013/README.html">ADR#9316364013</a>: Reserved repository directories</li><li><a href="./../5842232571/README.html">ADR#5842232571</a>: Language workspaces</li><li><a href="./../6647967335/README.html">ADR#6647967335</a>: mise tasks and shared code</li><li><a href="./../4711775939/README.html">ADR#4711775939</a>: Schema source directories</li><li><a href="./../2078011537/README.html">ADR#2078011537</a>: Operational assets</li></ul>`,18)])])}const u=t(r,[["render",n]]);export{g as __pageData,u as default};
